39	namespace Emby.Server.Implementations.Library
40	{
41	    public class MediaSourceManager : IMediaSourceManager, IDisposable
42	    {
43	        // Do not use a pipe here because Roku http requests to the server will fail, without any explicit error message.
44	        private const char LiveStreamIdDelimiter = '_';
45	
46	        private readonly IServerApplicationHost _appHost;
47	        private readonly IItemRepository _itemRepo;
48	        private readonly IUserManager _userManager;
49	        private readonly ILibraryManager _libraryManager;
50	        private readonly IFileSystem _fileSystem;
51	        private readonly ILogger<MediaSourceManager> _logger;
52	        private readonly IUserDataManager _userDataManager;
53	        private readonly IMediaEncoder _mediaEncoder;
54	        private readonly ILocalizationManager _localizationManager;
55	        private readonly IApplicationPaths _appPaths;
56	        private readonly IDirectoryService _directoryService;
57	        private readonly IMediaStreamRepository _mediaStreamRepository;
58	        private readonly IMediaAttachmentRepository _mediaAttachmentRepository;
59	        private readonly ConcurrentDictionary<string, ILiveStream> _openStreams = new ConcurrentDictionary<string, ILiveStream>(StringComparer.OrdinalIgnoreCase);
60	        private readonly AsyncNonKeyedLocker _liveStreamLocker = new(1);
61	        private readonly JsonSerializerOptions _jsonOptions = JsonDefaults.Options;
62	
63	        private IMediaSourceProvider[] _providers;
64	
65	        public MediaSourceManager(
66	            IServerApplicationHost appHost,
67	            IItemRepository itemRepo,
68	            IApplicationPaths applicationPaths,
69	            ILocalizationManager localizationManager,
70	            IUserManager userManager,
71	            ILibraryManager libraryManager,
72	            ILogger<MediaSourceManager> logger,
73	            IFileSystem fileSystem,
74	            IUserDataManager userDataManager,
75	            IMediaEncoder mediaEncoder,
76	            IDirectoryService directoryService,
77	            IMediaStreamRepository mediaStreamRepository,
78	            IMediaAttachmentRepository mediaAttachmentRepository)
79	        {
80	            _appHost = appHost;
81	            _itemRepo = itemRepo;
82	            _userManager = userManager;
83	            _libraryManager = libraryManager;
84	            _logger = logger;
85	            _fileSystem = fileSystem;
86	            _userDataManager = userDataManager;
87	            _mediaEncoder = mediaEncoder;
88	            _localizationManager = localizationManager;
89	            _appPaths = applicationPaths;
90	            _directoryService = directoryService;
91	            _mediaStreamRepository = mediaStreamRepository;
92	            _mediaAttachmentRepository = mediaAttachmentRepository;
93	        }
94	
95	        public void AddParts(IEnumerable<IMediaSourceProvider> providers)
96	        {
97	            _providers = providers.ToArray();
98	        }
99	
100	        public IReadOnlyList<MediaStream> GetMediaStreams(MediaStreamQuery query)
101	        {
102	            var list = _mediaStreamRepository.GetMediaStreams(query);
103	
104	            foreach (var stream in list)
105	            {
106	                stream.SupportsExternalStream = StreamSupportsExternalStream(stream);
107	            }
108	
109	            return list;
110	        }
111	
112	        private static bool StreamSupportsExternalStream(MediaStream stream)
113	        {
114	            if (stream.IsExternal)
115	            {
116	                return true;
117	            }
118	
119	            if (stream.IsTextSubtitleStream)
120	            {
121	                return true;
122	            }
123	
124	            if (stream.IsPgsSubtitleStream)
125	            {
126	                return true;
127	            }
128	
129	            return false;
130	        }
131	
132	        public IReadOnlyList<MediaStream> GetMediaStreams(Guid itemId)
133	        {
134	            var list = GetMediaStreams(new MediaStreamQuery
135	            {
136	                ItemId = itemId
137	            });
138	
139	            return GetMediaStreamsForItem(list);
140	        }
141	
142	        private IReadOnlyList<MediaStream> GetMediaStreamsForItem(IReadOnlyList<MediaStream> streams)
143	        {
144	            foreach (var stream in streams)
145	            {
146	                if (stream.Type == MediaStreamType.Subtitle)
147	                {
148	                    stream.SupportsExternalStream = StreamSupportsExternalStream(stream);
149	                }
150	            }
151	
152	            return streams;
153	        }
154	
155	        /// <inheritdoc />
156	        public IReadOnlyList<MediaAttachment> GetMediaAttachments(MediaAttachmentQuery query)
157	        {
158	            return _mediaAttachmentRepository.GetMediaAttachments(query);
159	        }
160	
161	        /// <inheritdoc />
162	        public IReadOnlyList<MediaAttachment> GetMediaAttachments(Guid itemId)
163	        {
164	            return GetMediaAttachments(new MediaAttachmentQuery
165	            {
166	                ItemId = itemId
167	            });
168	        }
169	
170	        public async Task<IReadOnlyList<MediaSourceInfo>> GetPlaybackMediaSources(BaseItem item, User user, bool allowMediaProbe, bool enablePathSubstitution, CancellationToken cancellationToken)
171	        {
172	            var mediaSources = GetStaticMediaSources(item, enablePathSubstitution, user);
173	
174	            // If file is strm or main media stream is missing, force a metadata refresh with remote probing
175	            if (allowMediaProbe && mediaSources[0].Type != MediaSourceType.Placeholder
176	                && (item.Path.EndsWith(".strm", StringComparison.OrdinalIgnoreCase)
177	                    || (item.MediaType == MediaType.Video && mediaSources[0].MediaStreams.All(i => i.Type != MediaStreamType.Video))
178	                    || (item.MediaType == MediaType.Audio && mediaSources[0].MediaStreams.All(i => i.Type != MediaStreamType.Audio))))
179	            {
180	                await item.RefreshMetadata(
181	                    new MetadataRefreshOptions(_directoryService)
182	                    {
183	                        EnableRemoteContentProbe = true,
184	                        MetadataRefreshMode = MetadataRefreshMode.FullRefresh
185	                    },
186	                    cancellationToken).ConfigureAwait(false);
187	
188	                mediaSources = GetStaticMediaSources(item, enablePathSubstitution, user);
189	            }
190	
191	            var dynamicMediaSources = await GetDynamicMediaSources(item, cancellationToken).ConfigureAwait(false);
192	
193	            var list = new List<MediaSourceInfo>();
194	
195	            list.AddRange(mediaSources);
196	
197	            foreach (var source in dynamicMediaSources)
198	            {
199	                // Validate that this is actually possible
200	                if (source.SupportsDirectStream)
201	                {
202	                    source.SupportsDirectStream = SupportsDirectStream(source.Path, source.Protocol);
203	                }
204	
205	                if (user is not null)
206	                {
207	                    SetDefaultAudioAndSubtitleStreamIndices(item, source, user);
208	
209	                    if (item.MediaType == MediaType.Audio)
210	                    {
211	                        source.SupportsTranscoding = user.HasPermission(PermissionKind.EnableAudioPlaybackTranscoding);
212	                    }
213	                    else if (item.MediaType == MediaType.Video)
214	                    {
215	                        source.SupportsTranscoding = user.HasPermission(PermissionKind.EnableVideoPlaybackTranscoding);
216	                        source.SupportsDirectStream = user.HasPermission(PermissionKind.EnablePlaybackRemuxing);
217	                    }
218	                }
219	
220	                list.Add(source);
221	            }
222	
223	            return SortMediaSources(list).ToArray();
224	        }
225	
226	        /// <inheritdoc />>
227	        public MediaProtocol GetPathProtocol(string path)
228	        {
229	            if (string.IsNullOrEmpty(path))
230	            {
231	                return MediaProtocol.File;
232	            }
233	
234	            if (path.StartsWith("Rtsp", StringComparison.OrdinalIgnoreCase))
235	            {
236	                return MediaProtocol.Rtsp;
237	            }
238	
239	            if (path.StartsWith("Rtmp", StringComparison.OrdinalIgnoreCase))
240	            {
241	                return MediaProtocol.Rtmp;
242	            }
243	
244	            if (path.StartsWith("Http", StringComparison.OrdinalIgnoreCase))
245	            {
246	                return MediaProtocol.Http;
247	            }
248	
249	            if (path.StartsWith("rtp", StringComparison.OrdinalIgnoreCase))
250	            {
251	                return MediaProtocol.Rtp;
252	            }
253	
254	            if (path.StartsWith("ftp", StringComparison.OrdinalIgnoreCase))
255	            {
256	                return MediaProtocol.Ftp;
257	            }
258	
259	            if (path.StartsWith("udp", StringComparison.OrdinalIgnoreCase))
260	            {
261	                return MediaProtocol.Udp;
262	            }
263	
264	            return _fileSystem.IsPathFile(path) ? MediaProtocol.File : MediaProtocol.Http;
265	        }
266	
267	        public bool SupportsDirectStream(string path, MediaProtocol protocol)
268	        {
269	            if (protocol == MediaProtocol.File)
270	            {
271	                return true;
272	            }
273	
274	            if (protocol == MediaProtocol.Http)
275	            {
276	                if (path is not null)
277	                {
278	                    if (path.Contains(".m3u", StringComparison.OrdinalIgnoreCase))
279	                    {
280	                        return false;
281	                    }
282	
283	                    return true;
284	                }
285	            }
286	
287	            return false;
288	        }
289	
290	        private async Task<IEnumerable<MediaSourceInfo>> GetDynamicMediaSources(BaseItem item, CancellationToken cancellationToken)
291	        {
292	            var tasks = _providers.Select(i => GetDynamicMediaSources(item, i, cancellationToken));
293	            var results = await Task.WhenAll(tasks).ConfigureAwait(false);
294	
295	            return results.SelectMany(i => i);
296	        }
297	
298	        private async Task<IEnumerable<MediaSourceInfo>> GetDynamicMediaSources(BaseItem item, IMediaSourceProvider provider, CancellationToken cancellationToken)
299	        {
300	            try
301	            {
302	                var sources = await provider.GetMediaSources(item, cancellationToken).ConfigureAwait(false);
303	                var list = sources.ToList();
304	
305	                foreach (var mediaSource in list)
306	                {
307	                    mediaSource.InferTotalBitrate();
308	
309	                    SetKeyProperties(provider, mediaSource);
310	                }
311	
312	                return list;
313	            }
314	            catch (Exception ex)
315	            {
316	                _logger.LogError(ex, "Error getting media sources");
317	                return [];
318	            }
319	        }
320	
321	        private static void SetKeyProperties(IMediaSourceProvider provider, MediaSourceInfo mediaSource)
322	        {
323	            var prefix = provider.GetType().FullName.GetMD5().ToString("N", CultureInfo.InvariantCulture) + LiveStreamIdDelimiter;
324	
325	            if (!string.IsNullOrEmpty(mediaSource.OpenToken) && !mediaSource.OpenToken.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
326	            {
327	                mediaSource.OpenToken = prefix + mediaSource.OpenToken;
328	            }
329	
330	            if (!string.IsNullOrEmpty(mediaSource.LiveStreamId) && !mediaSource.LiveStreamId.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
331	            {
332	                mediaSource.LiveStreamId = prefix + mediaSource.LiveStreamId;
333	            }
334	        }
335	
336	        public async Task<MediaSourceInfo> GetMediaSource(BaseItem item, string mediaSourceId, string liveStreamId, bool enablePathSubstitution, CancellationToken cancellationToken)
337	        {
338	            if (!string.IsNullOrEmpty(liveStreamId))
339	            {
340	                return await GetLiveStream(liveStreamId, cancellationToken).ConfigureAwait(false);
341	            }
342	
343	            var sources = await GetPlaybackMediaSources(item, null, false, enablePathSubstitution, cancellationToken).ConfigureAwait(false);
344	
345	            return sources.FirstOrDefault(i => string.Equals(i.Id, mediaSourceId, StringComparison.OrdinalIgnoreCase));
346	        }
347	
348	        public IReadOnlyList<MediaSourceInfo> GetStaticMediaSources(BaseItem item, bool enablePathSubstitution, User user = null)
349	        {
350	            ArgumentNullException.ThrowIfNull(item);
351	
352	            var hasMediaSources = (IHasMediaSources)item;
353	
354	            var sources = hasMediaSources.GetMediaSources(enablePathSubstitution);
355	
356	            if (user is not null)
357	            {
358	                foreach (var source in sources)
359	                {
360	                    SetDefaultAudioAndSubtitleStreamIndices(item, source, user);
361	
362	                    if (item.MediaType == MediaType.Audio)
363	                    {
364	                        source.SupportsTranscoding = user.HasPermission(PermissionKind.EnableAudioPlaybackTranscoding);
365	                    }
366	                    else if (item.MediaType == MediaType.Video)
367	                    {
368	                        source.SupportsTranscoding = user.HasPermission(PermissionKind.EnableVideoPlaybackTranscoding);
369	                        source.SupportsDirectStream = user.HasPermission(PermissionKind.EnablePlaybackRemuxing);
370	                    }
371	                }
372	            }
373	
374	            return sources;
375	        }
376	
377	        private IReadOnlyList<string> NormalizeLanguage(string language)
378	        {
379	            if (string.IsNullOrEmpty(language))
380	            {
381	                return [];
382	            }
383	
384	            var culture = _localizationManager.FindLanguageInfo(language);
385	            if (culture is not null)
386	            {
387	                return culture.Name.Contains('-', StringComparison.OrdinalIgnoreCase) ? [culture.Name] : culture.ThreeLetterISOLanguageNames;
388	            }
389	
390	            return [language];
391	        }
392	
393	        private void SetDefaultSubtitleStreamIndex(MediaSourceInfo source, UserItemData userData, User user, bool allowRememberingSelection)
394	        {
395	            if (userData is not null
396	                && userData.SubtitleStreamIndex.HasValue
397	                && user.RememberSubtitleSelections
398	                && user.SubtitleMode != SubtitlePlaybackMode.None
399	                && allowRememberingSelection)
400	            {
401	                var index = userData.SubtitleStreamIndex.Value;
402	                // Make sure the saved index is still valid
403	                if (index == -1 || source.MediaStreams.Any(i => i.Type == MediaStreamType.Subtitle && i.Index == index))
404	                {
405	                    source.DefaultSubtitleStreamIndex = index;
406	                    return;
407	                }
408	            }
409	
410	            var preferredSubs = NormalizeLanguage(user.SubtitleLanguagePreference);
411	
412	            var defaultAudioIndex = source.DefaultAudioStreamIndex;
413	            var audioLanguage = defaultAudioIndex is null
414	                ? null
415	                : source.MediaStreams.Where(i => i.Type == MediaStreamType.Audio && i.Index == defaultAudioIndex).Select(i => i.Language).FirstOrDefault();
416	
417	            source.DefaultSubtitleStreamIndex = MediaStreamSelector.GetDefaultSubtitleStreamIndex(
418	                source.MediaStreams,
419	                preferredSubs,
420	                user.SubtitleMode,
421	                audioLanguage);
422	
423	            MediaStreamSelector.SetSubtitleStreamScores(source.MediaStreams, preferredSubs, user.SubtitleMode, audioLanguage);
424	        }
425	
426	        private void SetDefaultAudioStreamIndex(MediaSourceInfo source, UserItemData userData, User user, bool allowRememberingSelection)
427	        {
428	            if (userData is not null && userData.AudioStreamIndex.HasValue && user.RememberAudioSelections && allowRememberingSelection)
429	            {
430	                var index = userData.AudioStreamIndex.Value;
431	                // Make sure the saved index is still valid
432	                if (source.MediaStreams.Any(i => i.Type == MediaStreamType.Audio && i.Index == index))
433	                {
434	                    source.DefaultAudioStreamIndex = index;
435	                    source.DefaultAudioIndexSource = AudioIndexSource.User;
436	                    return;
437	                }
438	            }
439	
440	            var preferredAudio = NormalizeLanguage(user.AudioLanguagePreference);
441	
442	            source.DefaultAudioStreamIndex = MediaStreamSelector.GetDefaultAudioStreamIndex(source.MediaStreams, preferredAudio, user.PlayDefaultAudioTrack);
443	            if (user.PlayDefaultAudioTrack)
444	            {
445	                source.DefaultAudioIndexSource |= AudioIndexSource.Default;
446	            }
447	
448	            if (preferredAudio.Count > 0)
449	            {
450	                source.DefaultAudioIndexSource |= AudioIndexSource.Language;
451	            }
452	        }
453	
454	        public void SetDefaultAudioAndSubtitleStreamIndices(BaseItem item, MediaSourceInfo source, User user)
455	        {
456	            // Item would only be null if the app didn't supply ItemId as part of the live stream open request
457	            var mediaType = item?.MediaType ?? MediaType.Video;
458	
459	            if (mediaType == MediaType.Video)
460	            {
461	                var userData = item is null ? null : _userDataManager.GetUserData(user, item);
462	
463	                var allowRememberingSelection = item is null || item.EnableRememberingTrackSelections;
464	
465	                SetDefaultAudioStreamIndex(source, userData, user, allowRememberingSelection);
466	                SetDefaultSubtitleStreamIndex(source, userData, user, allowRememberingSelection);
467	            }
468	            else if (mediaType == MediaType.Audio)
469	            {
470	                var audio = source.MediaStreams.FirstOrDefault(i => i.Type == MediaStreamType.Audio);
471	
472	                if (audio is not null)
473	                {
474	                    source.DefaultAudioStreamIndex = audio.Index;
475	                }
476	            }
477	        }
478	
479	        private static IEnumerable<MediaSourceInfo> SortMediaSources(IEnumerable<MediaSourceInfo> sources)
480	        {
481	            return sources.OrderBy(i =>
482	            {
483	                if (i.VideoType.HasValue && i.VideoType.Value == VideoType.VideoFile)
484	                {
485	                    return 0;
486	                }
487	
488	                return 1;
489	            }).ThenBy(i => i.Video3DFormat.HasValue ? 1 : 0)
490	            .ThenByDescending(i =>
491	            {
492	                var stream = i.VideoStream;
493	
494	                return stream?.Width ?? 0;
495	            })
496	            .Where(i => i.Type != MediaSourceType.Placeholder);
497	        }
498	
499	        public async Task<Tuple<LiveStreamResponse, IDirectStreamProvider>> OpenLiveStreamInternal(LiveStreamRequest request, CancellationToken cancellationToken)
500	        {
501	            MediaSourceInfo mediaSource;
502	            ILiveStream liveStream;
503	
504	            using (await _liveStreamLocker.LockAsync(cancellationToken).ConfigureAwait(false))
505	            {
506	                var (provider, keyId) = GetProvider(request.OpenToken);
507	
508	                var currentLiveStreams = _openStreams.Values.ToList();
509	
510	                liveStream = await provider.OpenMediaSource(keyId, currentLiveStreams, cancellationToken).ConfigureAwait(false);
511	
512	                mediaSource = liveStream.MediaSource;
513	
514	                // Validate that this is actually possible
515	                if (mediaSource.SupportsDirectStream)
516	                {
517	                    mediaSource.SupportsDirectStream = SupportsDirectStream(mediaSource.Path, mediaSource.Protocol);
518	                }
519	
520	                SetKeyProperties(provider, mediaSource);
521	
522	                _openStreams[mediaSource.LiveStreamId] = liveStream;
523	            }
524	
525	            try
526	            {
527	                if (mediaSource.MediaStreams.Any(i => i.Index != -1) || !mediaSource.SupportsProbing)
528	                {
529	                    AddMediaInfo(mediaSource);
530	                }
531	                else
532	                {
533	                    // hack - these two values were taken from LiveTVMediaSourceProvider
534	                    string cacheKey = request.OpenToken;
535	
536	                    await new LiveStreamHelper(_mediaEncoder, _logger, _appPaths)
537	                        .AddMediaInfoWithProbe(mediaSource, false, cacheKey, true, cancellationToken)
538	                        .ConfigureAwait(false);
539	                }
540	            }
541	            catch (Exception ex)
542	            {
543	                _logger.LogError(ex, "Error probing live tv stream");
544	                AddMediaInfo(mediaSource);
545	            }
546	
547	            // TODO: @bond Fix
548	            var json = JsonSerializer.SerializeToUtf8Bytes(mediaSource, _jsonOptions);
549	            _logger.LogInformation("Live stream opened: {@MediaSource}", mediaSource);
550	            var clone = JsonSerializer.Deserialize<MediaSourceInfo>(json, _jsonOptions);
551	
552	            if (!request.UserId.IsEmpty())
553	            {
554	                var user = _userManager.GetUserById(request.UserId);
555	                var item = request.ItemId.IsEmpty()
556	                    ? null
557	                    : _libraryManager.GetItemById(request.ItemId);
558	                SetDefaultAudioAndSubtitleStreamIndices(item, clone, user);
559	            }
560	
561	            return new Tuple<LiveStreamResponse, IDirectStreamProvider>(new LiveStreamResponse(clone), liveStream as IDirectStreamProvider);
562	        }
563	
564	        private static void AddMediaInfo(MediaSourceInfo mediaSource)
565	        {
566	            mediaSource.DefaultSubtitleStreamIndex = null;
567	
568	            // Null this out so that it will be treated like a live stream
569	            if (mediaSource.IsInfiniteStream)
570	            {
571	                mediaSource.RunTimeTicks = null;
572	            }
573	
574	            var audioStream = mediaSource.MediaStreams.FirstOrDefault(i => i.Type == MediaStreamType.Audio);
575	
576	            if (audioStream is null || audioStream.Index == -1)
577	            {
578	                mediaSource.DefaultAudioStreamIndex = null;
579	            }
580	            else
581	            {
582	                mediaSource.DefaultAudioStreamIndex = audioStream.Index;
583	            }
584	
585	            var videoStream = mediaSource.MediaStreams.FirstOrDefault(i => i.Type == MediaStreamType.Video);
586	            if (videoStream is not null)
587	            {
588	                if (!videoStream.BitRate.HasValue)
589	                {
590	                    var width = videoStream.Width ?? 1920;
591	
592	                    if (width >= 3000)
593	                    {
594	                        videoStream.BitRate = 30000000;
595	                    }
596	                    else if (width >= 1900)
597	                    {
598	                        videoStream.BitRate = 20000000;
599	                    }
600	                    else if (width >= 1200)
601	                    {
602	                        videoStream.BitRate = 8000000;
603	                    }
604	                    else if (width >= 700)
605	                    {
606	                        videoStream.BitRate = 2000000;
607	                    }
608	                }
609	            }
610	
611	            // Try to estimate this
612	            mediaSource.InferTotalBitrate();
613	        }
