836	        {
837	            var stream = new MediaSourceInfo
838	            {
839	                EncoderPath = _appHost.GetApiUrlForLocalAccess() + "/LiveTv/LiveRecordings/" + info.Id + "/stream",
840	                EncoderProtocol = MediaProtocol.Http,
841	                Path = info.Path,
842	                Protocol = MediaProtocol.File,
