861	        public async Task CloseLiveStream(string id)
862	        {
863	            ArgumentException.ThrowIfNullOrEmpty(id);
864	
865	            using (await _liveStreamLocker.LockAsync().ConfigureAwait(false))
866	            {
867	                if (_openStreams.TryGetValue(id, out ILiveStream liveStream))
868	                {
869	                    liveStream.ConsumerCount--;
870	
871	                    _logger.LogInformation("Live stream {0} consumer count is now {1}", liveStream.OriginalStreamId, liveStream.ConsumerCount);
872	
873	                    if (liveStream.ConsumerCount <= 0)
874	                    {
875	                        _openStreams.TryRemove(id, out _);
876	
877	                        _logger.LogInformation("Closing live stream {0}", id);
878	
879	                        await liveStream.Close().ConfigureAwait(false);
880	                        _logger.LogInformation("Live stream {0} closed successfully", id);
881	                    }
882	                }
883	            }
884	        }
885	
886	        private (IMediaSourceProvider MediaSourceProvider, string KeyId) GetProvider(string key)
887	        {
888	            ArgumentException.ThrowIfNullOrEmpty(key);
889	
890	            var keys = key.Split(LiveStreamIdDelimiter, 2);
891	
892	            var provider = _providers.FirstOrDefault(i => string.Equals(i.GetType().FullName.GetMD5().ToString("N", CultureInfo.InvariantCulture), keys[0], StringComparison.OrdinalIgnoreCase));
893	
894	            var splitIndex = key.IndexOf(LiveStreamIdDelimiter, StringComparison.Ordinal);
895	            var keyId = key.Substring(splitIndex + 1);
896	
897	            return (provider, keyId);
898	        }
899	
900	        /// <inheritdoc />
901	        public void Dispose()
902	        {
903	            Dispose(true);
904	            GC.SuppressFinalize(this);
905	        }
906	
907	        /// <summary>
908	        /// Releases unmanaged and - optionally - managed resources.
909	        /// </summary>
910	        /// <param name="dispose"><c>true</c> to release both managed and unmanaged resources; <c>false</c> to release only unmanaged resources.</param>
911	        protected virtual void Dispose(bool dispose)
912	        {
913	            if (dispose)
914	            {
915	                foreach (var key in _openStreams.Keys.ToList())
916	                {
917	                    CloseLiveStream(key).GetAwaiter().GetResult();
918	                }
919	
920	                _liveStreamLocker.Dispose();
921	            }
922	        }
923	    }
924	}
